logger = ProfilingLogger(__name__)


@typechecked
class ProfileReport(SerializeReport, ExpectationsReport):
    """Generate a profile report from a Dataset stored as a pandas `DataFrame`."""

    _description_set = None
    _report = None
    _html = None
    _widgets = None
    _json = None
    config: Settings

    def __init__(
        self,
        df: Optional[Union[pd.DataFrame, Any]] = None,
        minimal: bool = False,
        tsmode: bool = False,
        sortby: Optional[str] = None,
        sensitive: bool = False,
        explorative: bool = False,
        sample: Optional[dict] = None,
        config_file: Optional[Union[Path, str]] = None,
        lazy: bool = True,
        typeset: Optional[ProfilingTypeSet] = None,
        summarizer: Optional[ProfilingSummarizer] = None,
        config: Optional[Settings] = None,
        type_schema: Optional[dict] = None,
        **kwargs,
    ):
        display_banner()
        self.__validate_inputs(df, minimal, tsmode, config_file, lazy)
        use_spark = df is not None and df.__class__.__module__.startswith("pyspark")
        report_config = (config.copy(deep=True) if config is not None else (SparkSettings() if use_spark else Settings()))
        if config_file is not None:
            report_config = report_config.update(Settings.from_file(config_file).dict())
        if minimal:
            report_config = report_config.update(Settings.from_file(Path(__file__).with_name("config_minimal.yaml")).dict())
        if sensitive:
            report_config = report_config.update(Config.get_arg_groups("sensitive"))
        if explorative:
            report_config = report_config.update(Config.get_arg_groups("explorative"))
        shorthand_args, remaining_kwargs = Config.shorthands(kwargs)
        for key, value in shorthand_args.items():
            report_config = report_config.update({key: value})
        if remaining_kwargs:
            report_config = report_config.update(remaining_kwargs)
        if tsmode:
            report_config.vars.timeseries.active = True
            report_config.vars.timeseries.sortby = sortby
        if sortby is not None and isinstance(df, pd.DataFrame):
            df = df.sort_values(sortby)
        self.config = report_config
        self.sample = sample
        self.df = self.__initialize_dataframe(df, report_config)
        self._typeset = typeset or ProfilingTypeSet(report_config, type_schema=type_schema or {})
        self._summarizer = summarizer or ProfilingSummarizer(self._typeset, use_spark=use_spark)
        logger.info_def_report(self.df if self.df is not None else pd.DataFrame(), tsmode)
        if not lazy and self.df is not None:
            _ = self.description_set

    @staticmethod
    def __validate_inputs(
        df: Optional[Union[pd.DataFrame, Any]],
        minimal: bool,
        tsmode: bool,
        config_file: Optional[Union[Path, str]],
        lazy: bool,
    ) -> None:
        if df is None and not lazy:
            raise ValueError("A dataframe is required when lazy is False.")
        if minimal and config_file is not None:
            raise ValueError("Minimal mode and config_file are mutually exclusive.")
        if df is not None and isinstance(df, pd.DataFrame) and df.empty:
            raise ValueError("DataFrame is empty. Please provide a non-empty DataFrame.")
        if df is not None and df.__class__.__module__.startswith("pyspark") and tsmode:
            raise NotImplementedError("Time series mode is only available for pandas DataFrames.")

    @staticmethod
    def __initialize_dataframe(df, report_config):
        if df is None:
            return None
        return preprocess(report_config, df)

    @property
    def typeset(self) -> Optional[ProfilingTypeSet]:
        return self._typeset

    @property
    def summarizer(self) -> ProfilingSummarizer:
        return self._summarizer

    def invalidate_cache(self, subset: Optional[str] = None) -> None:
        if subset not in {None, "rendering", "report"}:
            raise ValueError("subset must be None, 'rendering', or 'report'")
        if subset in {None, "rendering"}:
            self._html = None
            self._json = None
            self._widgets = None
        if subset in {None, "report"}:
            self._report = None
            self._description_set = None

    def get_duplicates(self) -> Optional[pd.DataFrame]:
        return self.get_description().duplicates

    def get_sample(self) -> dict:
        return {sample.name: sample.data for sample in self.get_description().sample}

    def get_description(self):
        return self.description_set

    def get_rejected_variables(self) -> set:
        description = self.get_description()
        rejected = {name for name, value in description.variables.items() if value.get("type") == "Unsupported"}
        for alert in description.alerts:
            if getattr(alert, "column_name", None) and alert.alert_type_name in {"constant", "rejected", "unsupported"}:
                rejected.add(alert.column_name)
        return rejected

    @property
    def description_set(self):
        if self._description_set is None:
            if self.df is None:
                raise ValueError("No dataframe was provided.")
            self._description_set = describe(self.config, self.df, self.summarizer, self.typeset, sample=self.sample)
        return self._description_set

    @property
    def report(self):
        if self._report is None:
            self._report = get_report_structure(self.config, self.description_set)
        return self._report

    def _render_html(self) -> str:
        structure = HTMLReport(self.report)
        return structure.render()

    def _render_widgets(self) -> Any:
        structure = WidgetReport(self.report)
        return structure.render()

    def _render_json(self) -> str:
        return json.dumps(format_summary(self.description_set), default=str)

    @property
    def html(self) -> str:
        if self._html is None:
            self._html = self._render_html()
        return self._html

    @property
    def json(self) -> str:
        if self._json is None:
            self._json = self._render_json()
        return self._json

    @property
    def widgets(self) -> Any:
        if self._widgets is None:
            self._widgets = self._render_widgets()
        return self._widgets

    def to_file(self, output_file: Union[str, Path], silent: bool = True) -> None:
        output_file = Path(output_file)
        suffix = output_file.suffix.lower()
        if suffix == ".json":
            output_file.write_text(self.to_json(), encoding="utf-8")
            return
        if suffix != ".html":
            warnings.warn("Unknown suffix, writing HTML output instead.", stacklevel=2)
            output_file = output_file.with_suffix(".html")
        output_file.write_text(self.to_html(), encoding="utf-8")
        if not self.config.html.inline:
            create_html_assets(self.config, output_file)

    def to_html(self) -> str:
        return self.html

    def to_json(self) -> str:
        return self.json

    def to_notebook_iframe(self) -> None:
        return get_notebook_iframe(self.config, self)

    def to_widgets(self) -> None:
        return self.widgets

    def compare(self, other: "ProfileReport", config: Optional[Settings] = None) -> "ProfileReport":
        return compare_reports([self, other], config=config)

