    if widgets is None:
        return [item.render() for item in items]
    return widgets.GridBox(
        [item.render() for item in items],
        layout=widgets.Layout(grid_template_columns=f"repeat({max(len(items),1)}, minmax(0, 1fr))", gap="12px"),
    )


def get_batch_grid(items: List, batch_size: int, titles: bool, subtitles: bool):
    if widgets is None:
        return [item.render() for item in items]
    children = []
    for item in items:
        if titles:
            children.append(widgets.HTML(f"<h4>{escape(item.name)}</h4>"))
        elif subtitles:
            children.append(widgets.HTML(f"<h5><em>{escape(item.name)}</em></h5>"))
        children.append(item.render())
